import itertools
import json

def solve_puzzle():
    # Define houses and attributes
    houses = [1, 2]  # left to right
    names = ["Arnold", "Eric"]
    vacations = ["beach", "mountain"]

    solutions = []

    # Iterate over all possible bijective assignments of names and vacations to houses
    for name_perm in itertools.permutations(names):
        house_to_name = {house: name_perm[i] for i, house in enumerate(houses)}
        name_to_house = {name: house for house, name in house_to_name.items()}

        for vac_perm in itertools.permutations(vacations):
            house_to_vac = {house: vac_perm[i] for i, house in enumerate(houses)}
            vac_to_house = {vac: house for house, vac in house_to_vac.items()}

            # Apply clues:
            # 1. Arnold is somewhere to the right of the person who loves beach vacations.
            if not (name_to_house["Arnold"] > vac_to_house["beach"]):
                continue

            solutions.append((house_to_name, house_to_vac))

    # Choose the (unique) solution; if multiple, pick the first
    if not solutions:
        raise ValueError("No solution found.")
    house_to_name, house_to_vac = solutions[0]

    # Prepare JSON output
    output = {
        "solution": {
            "header": ["House", "Name", "Vacation"],
            "rows": []
        }
    }

    for h in sorted(houses):
        output["solution"]["rows"].append([str(h), house_to_name[h], house_to_vac[h]])

    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
